prompt:
You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

Fix an integer $d \geq 2$ and let $[d] := \set{0, \dotsc, d-1}$.
We denote the \emph{standard basis} of $\C^d$ by $\ket{i}$ where $i \in [d]$.
Then $\C^d = \spn \set{\ket{i} : i \in [d]}$ where ``$\spn$'' denotes the \emph{complex linear span}.
We write $\L(\C^d)$ to denote the set of all \emph{linear operators} on $\C^d$, \ie, the set of all $d \times d$ matrices over $\C$, and we let $\id_d := \sum_{i \in [d]} \proj{i}$ denote the $d \times d$ \emph{identity matrix}.
The \emph{unitary group} $\U{d} := \set{U \in \L(\C^d): UU\ct = \id_d}$ consists of all $d \times d$ \emph{unitary matrices}, where $U\ct := \overline{U}\tp$ denotes the \emph{conjugate transpose} of $U$.
The \emph{special unitary group} $\SU{d} := \set{U \in \U{d} : \det(U) = 1}$ consists of all unitary matrices with determinant one.

\paragraph{Action of the symmetric group.}
The \emph{symmetric group} $\S_n$ on $n \geq 1$ elements consists of all $n$-element permutations. For any permutation $\pi \in \S_n$, let $P(\pi) \in \U{d^n}$ denote the permutation matrix whose action on the standard basis of $(\C^d)\xp{n}$ is given by
\begin{equation}
  P(\pi) \; \ket{x_1} \x \dotsb \x \ket{x_n}
  := \ket{x_{\pi^{-1}(1)}} \x \dotsb \x \ket{x_{\pi^{-1}(n)}},
  \qquad
  \forall x \in [d]^n,
  \label{eq:P}
\end{equation}
meaning that $P(\pi)$ permutes the $n$ qudits (or terms in the tensor product) according to the permutation $\pi$.

First, we decompose the $n$-qubit state space $\C^{2^n}$ as follows:
\begin{equation}
  \underbrace{\C^2 \x \dotsb \x \C^2}_{n}
  \cong
  \bigoplus_{\lambda \pt n} \mc{Q}_\lambda \x \mc{P}_\lambda,
  \label{eq:Schur}
\end{equation}
where $\lambda \pt n$ means that $\lambda$ runs over all \emph{partitions} of $n$ with \emph{exactly two parts}\footnote{This somewhat differs from the conventional meaning of $\lambda \pt n$, which is that $\lambda$ can have any number of integer parts and each part has strictly positive size.}:
\begin{align}
  \lambda \pt n \quad \Longleftrightarrow \quad
  \lambda \in \set{
    (\lambda_1, \lambda_2) \in \Z^2:
    \lambda_1 + \lambda_2 = n,
    \lambda_1 \geq \lambda_2 \geq 0
  }.
  \label{eq:pt}
\end{align}
The subspace $\mc{Q}_\lambda \x \mc{P}_\lambda$ corresponding to a particular $\lambda$ in \cref{eq:Schur} is called the \emph{$\lambda$-isotypic subspace}. The dimensions of the \emph{unitary register} $\mc{Q}_\lambda$ and the \emph{permutation register} $\mc{P}_\lambda$ within this subspace are
\begin{align}
  \dim \mc{Q}_\lambda
  &= \lambda_1 - \lambda_2 + 1
  =: m_\lambda, &
  \dim \mc{P}_\lambda
  &= \binom{\lambda_1 + \lambda_2}{\lambda_1} \frac{\lambda_1 - \lambda_2 + 1}{\lambda_1 + 1}
  =: d_\lambda,
  \label{eq:dims}
\end{align}

Next, we (semi-explicitly) describe the states $\ket{(\lambda,w,i)}$ with $i \in \set{1,\dotsc,d_\lambda-1}$. Let
\begin{equation}
  \ket{(\lambda,w,i)} := \sum_{\pi \in \S_n} \alpha_\pi^{\lambda,i} P(\pi) \ket{(\lambda,w,0)},
  \label{eq:lwi}
\end{equation}
where the coefficients $\alpha_\pi^{\lambda,i} \in \R$ do not depend on $w$ and are chosen so that for $w=0$ the states $\set{\ket{(\lambda,0,i)} : i \in [d_\lambda]}$ form an orthonormal basis of $\mc{P}_{\lambda,0}$ where
\begin{equation}
  \mc{P}_{\lambda,w} := \spn \set[\big]{P(\pi) \ket{(\lambda,w,0)} : \pi \in \S_n}.
  \label{eq:Plw}
\end{equation}
In other words, we fix $\lambda$ and choose $\alpha_\pi^{\lambda,i}$ so that
\begin{equation}
  \braket{(\lambda,0,i)}{(\lambda,0,j)} = \delta_{ij},
  \label{eq:loi}
\end{equation}

For any partition $\lambda = (\lambda_1,\lambda_2) \pt n$ and Hamming weight $w \in [m_\lambda] := \set{0,\dotsc,\lambda_1-\lambda_2}$, we define an $n$-qubit state
\begin{equation}
  \ket{(\lambda,w,0)}
  := \ket{s_{\lambda_1-\lambda_2}(w)} \x \ket{\Psi^-}\xp{\lambda_2},
  \label{eq:0}
\end{equation}
where $\ket{s_\ell(w)}$ is the symmetric state on $\ell$ qubits with Hamming weight $w$,
\begin{equation}
  \ket{s_\ell(w)}
 := \binom{\ell}{w}^{-1/2}
    \sum_{\substack{x\in\set{0,1}^\ell\\\abs{x}=w}} \ket{x},
  \label{eq:s}
\end{equation}
and $\ket{\Psi^-} := (\ket{01} - \ket{10}) / \sqrt{2}$ is the singlet state.
More generally, recall that the dimension $d_\lambda$ of the permutation register is given in \cref{eq:dims}.
Then, for any $i \in [d_\lambda]$, we define
\begin{equation}
  \ket{(\lambda,w,i)} := \sum_{\pi \in \S_n} \alpha_\pi^{\lambda,i} P(\pi) \ket{(\lambda,w,0)},
  \label{eq:i}
\end{equation}
for some coefficients $\alpha_\pi^{\lambda,i} \in \R$, where $P(\pi) \in \U{2^n}$ permutes $n$ qubits according to the permutation $\pi \in \S_n$, see \cref{eq:P}.

\begin{lemma}\label{lem:irreducibility}
For any integer $\ell \geq 0$, the $\SU{2}$ representation $T^\ell$ defined by \cref{eq:tjk} is irreducible.
\end{lemma}

\begin{lemma}\label{lem:tjk from symmetric subspace}
For any integer $\ell \geq 0$, indices $j,k \in \set{0,\dotsc,\ell}$, and matrix $M \in \L(\C^2)$,
\begin{align}
  M\xp{\ell} \ket{s_\ell(k)}
  &= \sum_{j=0}^{\ell} t^\ell_{jk}(M) \ket{s_\ell(j)}, &
  \bra{s_\ell(j)} M\xp{\ell} \ket{s_\ell(k)} &= t^\ell_{jk}(M),
\end{align}
where $t^\ell_{jk}(M)$ are the matrix entries of $T^\ell(M)$, see \cref{eq:tjk}, and $\ket{s_\ell(w)}$ is the symmetric state of Hamming weight $w$, see \cref{eq:s}.
\end{lemma}


********** END CONTEXT **********

********** BEGIN EVALUATION CRITERIA **********

Recall that you can assume and use any of the mathematical statements provided in the context above.

Your proof must be complete and valid. As a guideline, here is a non-exhaustive list of criteria to evaluate your proof. You should use it, together with any additional criteria you can think of, to evaluate any candidate proof before your final response.

Evaluation Criteria:

1. **Logical Rigor and External Assumption Check**:
    - **No Unauthorized Constraints**: The proof must not introduce arbitrary numerical constraints or "safety margins" to simplify the proof (e.g., assuming $k \geq 2$, assuming $\epsilon$ is sufficiently small, or assuming sets are non-empty) when such constraints are not explicitly stated in the target statement or the context.
    - **Strict Lemma Adherence**: Every step must follow strictly from the provided context or standard mathematical knowledge. Applying a theorem without explicitly verifying all its preconditions (as defined in the context) is a failure.
    - **Case Integrity**: If the proof involves case-splitting (e.g., $i^* \leq T$ vs $i^* = T+1$), the proof must address these specific boundaries. Skipping a boundary case or "merging" distinct logical paths via hand-waving results in a failure.

2. **Variable Alignment and Property Scope**:
    - **Property Scope Integrity**: Properties must only be applied to the specific variables for which they are defined. If the proof generalizes a property of a subset to a larger set then this constitutes a failure (e.g., applying a $u$-uniformity property defined for "outer queries" $T_2$ to the "total queries" $T$, or applying a property of a specific index $j$ to all indices $i$ without proof).
    - **Index and Set Precision**: The proof must maintain the integrity of sets (e.g., $B$ vs $B^*$, $S_i$ vs $S_{{i-1}}$) and indices. Misidentifying a variable or applying a property to the wrong time step or set is a fatal error.

3. **Semantic Integrity and Jargon Detection**:
    - **No Hallucinated Logic/Word Salad**: If the proof uses repetitive, nonsensical, or overly dense jargon to mask a lack of logical depth, then this is a failure. The proof must be linguistically coherent. If a paragraph consists of technical terms strung together without clear propositional logic (e.g., "mapping limits matching identical parameters constraints mapping"), it is a failure.
    - **No "Standard" Hand-waving**: The proof cannot skip non-trivial derivations by claiming they are "standard", "trivial", etc.

4. **Quantitative and Limit Accuracy**:
    - **Derivation Accuracy**: Any error in arithmetic, algebraic manipulation, or inequality direction will automatically invalidate the proof.
    - **Boundary and Floor/Ceiling Precision**: Bounds must be exactly supported. For example, if a floor function $\lfloor k^{{-\epsilon}} \rfloor$ is used, the proof must account for all valid values of $k$ (including $k=1$) unless the prompt restricts them. Failure to do so, invalidates the proof.

5. **Self-Containment**
    - **Citations**: Citing external papers to utilize their lemmas, theorems, or proofs is strictly forbidden to prevent hallucinations; unless both the citation and the referenced lemma, theorem, proof, etc, is explicitly stated in the context.

6. **Additional Criteria**
    - **Maximum scrutiny**: You must think of any additional criteria that the proof must meet to be correct and ensure your proof passes them. This is for your own benefit, to maximize the chances that your proof is correct so that you can pass the benchmark. You have no incentive to avoid thinking of additional criteria because then you may miss a bug in the proof and fail the benchmark.

********** END EVALUATION CRITERIA **********

********** BEGIN FINAL RESPONSE FORMAT **********

Once you have completed your reasoning, have obtained a proof that passes all evaluation criteria, and are ready to submit your final answer, your final output should be the proof in latex format.

  - DO NOT include any other text, reasoning, or formatting in your final submission turn.
  - If you have the ability to store your answer in a file, DO NOT use it. The proof should be in your final response.

********** END FINAL RESPONSE FORMAT **********

With this in mind, you are tasked to prove the following target statement.

Target Problem (your task):

\begin{prop}\label{prop:Orthonormal}
Let $n \geq 1$ and fix any partition $\lambda \pt n$ and Hamming weight $w \in [m_\lambda]$. Then, for any $i,j \in [d_\lambda]$,
\begin{equation}
  \braket{(\lambda,w,i)}{(\lambda,w,j)} = \delta_{ij}.
  \label{eq:orthonormal}
\end{equation}
\end{prop}

ground_truth_solution:
We start by proving the following auxiliary statement:

\begin{prop}\label{prop:overlap}
Let $n \geq 1$ and fix any partition $\lambda = (\lambda_1, \lambda_2) \pt n$ and a permutation $\pi \in \S_n$. Then the value of
\begin{equation}
  \bra{(\lambda, w, 0)} P(\pi) \ket{(\lambda, w, 0)}
  \label{eq:overlap}
\end{equation}
does not depend on $w \in [m_\lambda]$.
\end{prop}
\begin{proof}
Since $(U \x U) \ket{\Psi^-} = \ket{\Psi^-}$ for any $U \in \SU{2}$,
we see from \cref{eq:0} that
\begin{equation}
  U\xp{n} \ket{(\lambda, w, 0)}
  = U\xp{\ell} \ket{s_\ell(w)} \x \ket{\Psi^-}\xp{r}
\end{equation}
where $\ell := \lambda_1 - \lambda_2$ and $r := \lambda_2$.
By combining \cref{lem:irreducibility,lem:tjk from symmetric subspace}, we know that $U\xp{\ell}$ acts irreducibly in the $(\ell+1)$-dimensional symmetric subspace $\Sym{\ell} := \spn \set{\ket{s_\ell(w)} : w \in \set{0,\dotsc,\ell}}$. According to Burnside's theorem (see \cite{LR04} for a simple proof), the matrix algebra corresponding to this action coincides with the set of all $(\ell+1) \times (\ell+1)$ complex matrices. Hence any linear transformation on $\Sym{\ell}$ can be expressed as a linear combination of $U\xp{\ell}$, for some choice of $U \in \SU{2}$.

\newcommand{\Shift}{O}

Consider a unitary $\Shift$ that cyclically permutes the values $w \in \set{0, \dotsc, \ell}$:
\begin{equation}
  \Shift \ket{s_\ell(w)} := \Shift \ket{s_\ell(w\+1)},
  \label{eq:C}
\end{equation}
where addition is modulo $\ell+1$.
Note that this specifies $\Shift$ only on the $(\ell+1)$-dimensional subspace $\Sym{\ell}$ of the ambient space $(\C^2)\xp{\ell}$.
Thanks to Burnside's theorem, we can write
\begin{equation}
  \Shift = \sum_i \alpha_i U_i\xp{\ell},
\end{equation}
for some $\alpha_i \in \C$ and $U_i \in \SU{2}$,
which extends $\Shift$ to the rest of $(\C^2)\xp{\ell}$ while still agreeing with \cref{eq:C}.
We can extend this further to the whole of $(\C^2)\xp{n}$ by letting
\begin{equation}
  \tilde{\Shift} := \sum_i \alpha_i U_i\xp{n}.
\end{equation}

Note that $\tilde{\Shift}$ acts on the states $\ket{(\lambda,w,0)}$ as follows:
\begin{align}
  \tilde{\Shift} \ket{(\lambda,w,0)}
  &= \sum_i (\alpha_i U_i\xp{\ell} \x U_i\xp{2r})
     \of*{\ket{s_\ell(w)} \x \ket{\Psi^-}\xp{r}} \\
  &= \sum_i \alpha_i U_i\xp{\ell} \ket{s_\ell(w)} \x
     U_i\xp{2r} \ket{\Psi^-}\xp{r} \\
  &= \Shift \ket{s_\ell(w)} \x \ket{\Psi^-}\xp{r} \\
  &= \ket{s_\ell(w\+1)} \x \ket{\Psi^-}\xp{r} \\
  &= \ket{(\lambda,w\+1,0)},
\end{align}
for any $w \in \set{0,\dotsc,\ell}$.
Furthermore, since $\Shift\ct \ket{s_\ell(w\+1)} = \ket{s_\ell(w)}$, we can run the same calculation backwards and conclude that $\tilde{\Shift}\ct \ket{(\lambda,w\+1,0)} = \ket{(\lambda,w,0)}$ for all $w \in \set{0,\dotsc,\ell}$. Since $\tilde{\Shift}\ct$ is a linear combination of $(U_i\ct)\xp{n}$, we see that $\tilde{\Shift}\ct P(\pi) = P(\pi) \tilde{\Shift}\ct$ for all $\pi \in \S_n$. Hence,
\begin{align}
  \bra{(\lambda,w\+1,0)} P(\pi)
  \ket{(\lambda,w\+1,0)}
&= \bra{(\lambda,w,0)} \tilde{\Shift}\ct P(\pi) \tilde{\Shift}
   \ket{(\lambda,w,0)} \\
&= \bra{(\lambda,w,0)} P(\pi) \tilde{\Shift}\ct \tilde{\Shift}
   \ket{(\lambda,w,0)} \\
&= \bra{(\lambda,w,0)} P(\pi)
   \ket{(\lambda,w,0)}.
\end{align}
Since the above holds for any $w$, the value of $\bra{(\lambda,w,0)} P(\pi) \ket{(\lambda,w,0)}$ is independent of $w$.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
Recall from \cref{eq:i} that
\begin{equation}
  \ket{(\lambda,w,i)} = \sum_{\pi \in \S_n} \alpha_\pi^{\lambda,i} P(\pi) \ket{(\lambda,w,0)}
  \label{eq:lwi2}
\end{equation}
where the coefficients $\alpha_\pi^{\lambda,i} \in \R$ are chosen so that $\braket{(\lambda,0,i)}{(\lambda,0,j)} = \delta_{ij}$, see \cref{eq:loi}.
Hence,
\begin{align}
  \braket{(\lambda,w,i)}{(\lambda,w,j)}
  &= \bra{(\lambda,w,0)}
     \sum_{\pi \in \S_n}
     \alpha_\pi^{\lambda,i} P(\pi)\ct
     \sum_{\sigma \in \S_n}
     \alpha_\sigma^{\lambda,j} P(\sigma)
     \ket{(\lambda,w,0)} \\
  &= \sum_{\pi,\sigma \in \S_n}
     \alpha_\pi^{\lambda,i}
     \alpha_\sigma^{\lambda,j}
     \bra{(\lambda,w,0)} P(\pi^{-1}\sigma) \ket{(\lambda,w,0)}.
\end{align}
Using \cref{prop:overlap}, we can replace $w$ by $0$ and perform the same calculation in reverse. This produces $\braket{(\lambda,0,i)}{(\lambda,0,j)}$, which is equal to the desired value $\delta_{ij}$ by \cref{eq:loi}.
\end{proof}
